pub(super) fn for_api(gvk: GroupVersionKind) -> Result<KindCapability, Finding> {
    let api = gvk.api_version();
    let (fields, first, removed) = match (gvk.kind.as_str(), api.as_str()) {
        ("Pod", "v1") => (FIELDS_0.as_slice(), 20, None),
        ("Deployment", "apps/v1") => (FIELDS_1.as_slice(), 20, None),
        ("StatefulSet", "apps/v1") => (FIELDS_2.as_slice(), 20, None),
        ("DaemonSet", "apps/v1") => (FIELDS_3.as_slice(), 20, None),
        ("ReplicaSet", "apps/v1") => (FIELDS_4.as_slice(), 20, None),
        ("ReplicationController", "v1") => (FIELDS_5.as_slice(), 20, None),
        ("Job", "batch/v1") => (FIELDS_6.as_slice(), 20, None),
        ("CronJob", "batch/v1") => (FIELDS_7.as_slice(), 21, None),
        ("CronJob", "batch/v1beta1") => (FIELDS_8.as_slice(), 20, Some(version(25)?)),
        _ => return Err(Finding::error(FindingCode::InvalidRegistration, Phase::Decoding)),
    };
    Ok(KindCapability {
        gvk,
        scope: ResourceScope::Namespaced,
        api_since: version(first)?,
        api_removed: removed,
        fields,
    })
}
